<?php require '../includes/auth.php';require '../includes/header.php';$u=guard('admin',['payroll_manager']);csrf_check();
$F=['basic'=>'Basic','hra'=>'HRA','special'=>'Special Allowance','other_allow'=>'Other Allowances','bonus'=>'Performance Bonus','pf'=>'PF','esi'=>'ESI','pt'=>'Professional Tax','tds'=>'TDS','other_ded'=>'Other Deductions'];
if(($_POST['_action']??'')==='save'){$id=(int)$_POST['emp'];$v=array_map(fn($k)=>max(0,(float)$_POST[$k]),array_keys($F));
 db()->prepare("INSERT INTO employee_salaries(employee_id,".implode(',',array_keys($F)).") VALUES(?,".implode(',',array_fill(0,count($F),'?')).") ON CONFLICT(employee_id) DO UPDATE SET ".implode(',',array_map(fn($k)=>"$k=EXCLUDED.$k",array_keys($F))))->execute(array_merge([$id],$v));
 audit($u['id'],'Salary changed for employee #'.$id);flash('Salary saved (applies to future payroll runs only)');redirect("salaries.php?emp=$id");}
$emps=db()->query("SELECT id,employee_code,full_name FROM employees ORDER BY employee_code")->fetchAll();$sel=(int)($_GET['emp']??($emps[0]['id']??0));
$s=db()->prepare("SELECT * FROM employee_salaries WHERE employee_id=?");$s->execute([$sel]);$s=$s->fetch()?:[];page_head('Salary Structures',[],$u);?>
<form method="get" class="mb-3"><select class="form-select w-auto d-inline" name="emp" onchange="this.form.submit()"><?php foreach($emps as $x)echo'<option value="'.$x['id'].'"'.($x['id']==$sel?' selected':'').'>'.e($x['employee_code'].' – '.$x['full_name']).'</option>';?></select></form>
<form method="post" class="card p-3"><?=csrf_field()?><input type="hidden" name="_action" value="save"><input type="hidden" name="emp" value="<?=$sel?>"><div class="row g-2"><?php foreach($F as $k=>$l){?><div class="col-md-3"><label class="small"><?=e($l)?></label><input class="form-control" type="number" step="0.01" min="0" name="<?=$k?>" value="<?=e($s[$k]??0)?>"></div><?php }?></div><button class="btn btn-primary mt-3 align-self-start">Save monthly structure</button></form><?php page_foot();
